int get_jpeg_dimensions(unsigned char* data, unsigned int data_size, int* width, int* height) {
    // Check if the data starts with the JPEG Start of Image (SOI) marker (0xFFD8)
    if (data_size < 2 || data[0] != 0xFF || data[1] != 0xD8) {
        return -1;
    }

    unsigned int i = 2; // Skip the SOI marker

    while (i < data_size) {
        // Check for a marker (0xFF followed by a non-zero byte)
        if (data[i] == 0xFF && i + 1 < data_size && data[i + 1] != 0x00) {
            unsigned char marker = data[++i];

            // Look for the Start of Frame (SOF) marker (0xFFC0 - baseline JPEG)
            if (marker == 0xC0) {
                // Skip the next two bytes (length of the segment)
                if (i + 2 < data_size) {
                    i += 2;

                    // Check if there are at least 5 bytes left to read the height and width
                    if (i + 5 < data_size) {
                        // Read the height (2 bytes, big-endian)
                        *height = (data[i] << 8) | data[i + 1];

                        // Read the width (2 bytes, big-endian)
                        *width = (data[i + 2] << 8) | data[i + 3];

                        // Skip the precision byte
                        return 0;
                    }
                }
            }

            // Skip the rest of the segment (length indicates the number of bytes after the two length bytes)
            if (i + 1 < data_size) {
                unsigned int length = (data[i] << 8) | data[i + 1];
                i += length;
            }
        }

        i++;
    }

    return -1;
}

int get_jpeg_dimensions(unsigned char* data, unsigned int data_size, int* width, int* height) {
    // Check for the Start of Image (SOI) marker (0xFFD8)
    if (data_size < 2 || data[0] != 0xFF || data[1] != 0xD8) {
        return -1;
    }

    unsigned int i = 2;

    // Search for Start of Frame (SOF) marker (0xFFC0 to 0xFFCF)
    while (i < data_size) {
        if (data[i] == 0xFF) {
            if (i + 1 < data_size) {
                unsigned char next_byte = data[i + 1];
                if (next_byte >= 0xC0 && next_byte <= 0xCF && (next_byte & 0x0F) == 0) {
                    // Found a SOF marker
                    if (i + 6 >= data_size) {
                        return -1;
                    }
                    // Extract width (2 bytes) and height (2 bytes)
                    int image_width = (data[i + 3] << 8) | data[i + 4];
                    int image_height = (data[i + 5] << 8) | data[i + 6];
                    *width = image_width;
                    *height = image_height;
                    return 0;
                }
            }
        }
        i++;
    }

    return -1;
}

int get_jpeg_dimensions(unsigned char* data, unsigned int data_size, int* width, int* height) {
    if (data_size < 2 || data[0] != 0xFF || data[1] != 0xD8) {
        return -1; // Invalid SOI marker
    }

    unsigned int i = 2;
    while (i < data_size) {
        if (data[i] == 0xFF && i + 1 < data_size) {
            unsigned char marker = data[++i];
            if (marker == 0xC0 || marker == 0xC1 || marker == 0xC2 || marker == 0xC3 ||
                marker == 0xC5 || marker == 0xC6 || marker == 0xC7 || marker == 0xC9 ||
                marker == 0xCA || marker == 0xCB || marker == 0xCD || marker == 0xCE ||
                marker == 0xCF) {
                if (i + 1 < data_size) {
                    unsigned int length = (data[++i] << 8) | data[++i];
                    if (i + 3 < data_size && length >= 6) {
                        i += 2;
                        *height = (data[i] << 8) | data[i + 1];
                        *width = (data[i + 2] << 8) | data[i + 3];
                        return 0;
                    }
                }
            } else if (marker == 0x00 || marker == 0xD9 || marker == 0xDA) {
                break;
            } else if (marker == 0xE0 || marker == 0xFE) {
                continue;
            } else {
                if (i + 1 < data_size) {
                    unsigned int length = (data[++i] << 8) | data[++i];
                    i += (length - 2);
                } else {
                    break;
                }
            }
        } else {
            ++i;
        }
    }

    return -1;
}

int get_jpeg_dimensions(unsigned char* data, unsigned int data_size, int* width, int* height) {
    if (data_size < 2 || data[0] != 0xFF || data[1] != 0xD8) {
        return -1;
    }

    unsigned int i = 2;
    while (i < data_size) {
        if (data[i] == 0xFF && i + 1 < data_size) {
            unsigned int marker = data[++i];
            if (marker == 0xC0 && i + 4 < data_size) {
                i += 2;
                *height = (data[i] << 8) | data[i + 1];
                *width = (data[i + 2] << 8) | data[i + 3];
                return 0;
            } else if (marker == 0xC4 || (marker >= 0xC1 && marker <= 0xC3) || (marker >= 0xC5 && marker <= 0xCA) || (marker >= 0xCC && marker <= 0xCF)) {
                if (i + 1 < data_size) {
                    unsigned int length = (data[i] << 8) | data[i + 1];
                    i += length + 1;
                } else {
                    return -1;
                }
            } else if (marker == 0xD9 || marker == 0xD8) {
                break;
            } else {
                return -1;
            }
        } else {
            ++i;
        }
    }

    return -1;
}

int get_jpeg_dimensions(unsigned char* data, unsigned int data_size, int* width, int* height) {
    if (data_size < 2) {
        return -1;
    }

    // Check for Start of Image (SOI) marker
    if (data[0] != 0xFF || data[1] != 0xD8) {
        return -1;
    }

    // Search for Start of Frame (SOF) marker
    int i = 2;
    while (i < data_size - 1) {
        if (data[i] == 0xFF) {
            unsigned char marker = data[i + 1];
            if (marker >= 0xC0 && marker <= 0xCF) {
                // SOF marker found
                if (i + 6 >= data_size) {
                    return -1;
                }

                // Extract height and width
                *height = (data[i + 2] << 8) | data[i + 3];
                *width = (data[i + 4] << 8) | data[i + 5];

                return 0;
            }
        }
        i++;
    }

    return -1;
}
